const P=s=>`<p>${s}</p>`;
const answer=s=>`<p><strong>Eine mögliche Antwort</strong></p>${P(s)}`;
const files={
 'schwingungen.html':{suffix:'atlas73',answers:{
 schw_alltag_essay:answer('1. Bei einer Gitarrensaite schwingt die Saite quer um ihre gerade Ruhelage; Luftreibung und die Energieabgabe an den Resonanzkörper dämpfen sie. 2. Bei einem Auto schwingen Karosserie und Rad nach einer Bodenwelle um ihre statische Federlage; Stoßdämpfer wandeln Bewegungsenergie in innere Energie um. 3. Bei einem Lineal schwingt das freie Ende um seine unverformte Lage; Materialdämpfung und Schallabgabe lassen die Bewegung abklingen.'),
 schw_diagramme_essay:P('Grün: A = 1,5 cm, T = 3,0 s, f = 0,333 Hz. Rot: A = 2,0 cm, T = 6,0 ms = 0,006 s, f ≈ 167 Hz. Blau: A = 3,0 dm = 0,30 m. Das erste Maximum liegt bei etwa 4,7 ms, also bei T/4; T ≈ 18,8 ms und f ≈ 53 Hz. Der nächste Nulldurchgang bei etwa 9,4 ms bestätigt T/2. Die drei Diagramme verwenden unterschiedliche Einheiten.'),
 schw_messung_essay:answer('Der mechanische Schreiber zeichnet die Auslenkung eines Stimmgabelzinkens als seitliche Spur auf Ruß auf. Eine Zeitachse entsteht nur, wenn die Platte mit bekannter, möglichst konstanter Geschwindigkeit bewegt wird. Ein elektronischer Wegsensor misst ebenfalls Auslenkung, während die Messwerterfassung Zeitstempel mit bekannter Abtastrate liefert. Ein Mikrofon misst dagegen Schalldruck, also eine andere Messgröße. Der Computer kann Perioden und Amplituden vieler Schwingungen automatisch auswerten. Beim mechanischen Verfahren verfälschen ungleichmäßiges Ziehen und die Berührung des Zinkens die Spur; elektronisch können Kalibrierfehler und eine zu niedrige Abtastrate die Auswertung verfälschen.'),
 schw_hooke_plan:answer('Ich befestige die Feder senkrecht und messe ihre unbelastete Länge. Die unabhängige Größe ist die angehängte Masse bzw. F = mg, die abhängige Größe die Verlängerung x. Feder, Skala und Temperatur bleiben gleich. Nach jedem zusätzlichen Massestück warte ich bis zur Ruhe und lese x ohne Parallaxe ab. Ich trage F in N gegen x in m auf: Im hookeschen Bereich erwarte ich eine Ursprungsgerade mit Steigung D. Eine Kontrollmessung beim Entlasten prüft, ob die Feder zur Ausgangslänge zurückkehrt. Bei erkennbarer Nichtlinearität oder bleibender Dehnung breche ich die Belastung ab; der lineare Gültigkeitsbereich endet spätestens dort.'),
 schw_rechenaufgaben:P('Aufgabe 1: Für die bewegliche Rolle gilt Δx<sub>Feder</sub> = 2s. Die Änderung der Seilspannung ist 2Ds; zwei Seilstücke wirken auf die Masse. Somit F<sub>R</sub> = −4Ds und D<sub>eff</sub> = 4 · 50 N/m = 200 N/m. T = 2π√(2 kg / 200 N/m) = 0,628 s, f = 1/T = 1,59 Hz. Das lineare Rückstellgesetz begründet die harmonische Bewegung.')+P('Aufgabe 2: T = 10,0 s / 5 = 2,00 s. m<sub>ges</sub> = D(T/2π)² = 840 · (2/2π)² kg = 85,1 kg. Die Astronautenmasse ist 85,1 − 10,0 = 75,1 kg. Für den positiven Umkehrpunkt: s(t) = 0,50 m · cos(πt/s). Die Messung erfasst die träge Masse und benötigt keine Gewichtskraft.'),
 schw_faden_plan:answer('Ich messe die Länge vom Aufhängepunkt bis zum Schwerpunkt der Pendelmasse und lenke höchstens 5° aus. Für l = 0,20; 0,40; 0,60; 0,80; 1,00 m messe ich jeweils mehrmals die Dauer von zehn vollständigen Perioden mit gleichem Durchgangspunkt und gleicher Richtung. T ist die gemessene Zeit geteilt durch zehn. Die Modellwerte bei g = 9,81 m/s² sind 0,897; 1,269; 1,554; 1,794; 2,006 s, keine vorgetäuschten Messwerte. Im T-√l-Diagramm erwarte ich eine Ursprungsgerade mit Steigung 2π/√g ≈ 2,006 s/√m. Zwei Wiederholungen bei geänderter Masse und gleicher Länge sollten innerhalb der Messunsicherheit dieselbe Periodendauer liefern. Reaktionszeit, ungenau bestimmter Schwerpunkt, große Winkel und Reibung sind Fehlerquellen.'),
 schw_transfer_rechnen:P('Aufgabe 5: Zusätzlich verdrängtes Volumen As erzeugt den zusätzlichen Auftrieb ρgAs entgegen der Auslenkung. Daher m·s̈ = −ρAgs und D* = ρAg = 1000 · 2,0·10⁻⁴ · 9,81 N/m = 1,962 N/m. T = 2π√(0,015/1,962) s = 0,549 s. ω = √(D*/m) = 11,44 s⁻¹ und v<sub>max</sub> = ωA = 11,44 · 0,030 m/s = 0,343 m/s.')+P('Aufgabe 6: D = mg/s₀ = 0,200 · 9,81 / 0,40 N/m = 4,905 N/m. T = 2π√(m/D) = 1,269 s; f = 0,788 Hz; ω = √(D/m) = 4,952 s⁻¹. Bei A = 0,10 m ist v<sub>max</sub> = 0,495 m/s.'),
 schw_phase_essay:answer('Die Phase φ = ωt + φ₀ gibt den Winkel des rotierenden Zeigers und damit den Zeitpunkt innerhalb einer Periode an. Eine volle Periode entspricht 2π. Die Phasendifferenz ist der Winkel zwischen zwei gleich schnell rotierenden Zeigern. Im Bild beträgt sie π/2 = 90°, entsprechend einer Zeitverschiebung T/4. Bei diesem Abstand erreicht ein Schwinger gerade einen Umkehrpunkt, während der andere die Ruhelage passiert. Gleiche Auslenkung allein bedeutet keine gleiche Phase, weil die Bewegungsrichtungen verschieden sein können. Zeigerlänge und Zeigerwinkel zeigen Amplitude und Phase unabhängig voneinander.'),
 schw_energie_diagramm:answer('Aufgabe 1: Bei nach unten positiver Auslenkung und statischer Dehnung s₀ = mg/D ist die gesamte Spannenergie ½D(s₀+s)². Für s = +s₀ sind dies 2Ds₀²; die Elongationsenergie beträgt dagegen ½Ds₀², also ein Viertel davon. Die Änderung der Höhenenergie kompensiert den linearen Anteil der Spannenergie. Bei s = −s₀ ist die Feder im idealen Modell gerade entspannt, ihre Spannenergie null; trotzdem beträgt die Elongationsenergie erneut ½Ds₀². Aufgabe 2: Bei doppelter Masse verdoppeln sich Gewichtskraft und statische Dehnung. Die Gerade F<sub>Feder</sub> = Dx behält ihre Steigung, aber der Gleichgewichtspunkt wandert zu 2s₀. Gegenüber dieser neuen Ruhelage bleibt F<sub>R</sub> = −Ds und die Dreiecksfläche ½Ds² für denselben Auslenkungsbetrag unverändert. Die Periodendauer wächst um √2.'),
 schw_zeiger_rechnen:P('Maßstab zum Beispiel 1 cm Zeichnungslänge je 1 cm Amplitude: Der erste Zeiger verläuft von (0|0) nach (2|0), der zweite mit Länge 5 cm unter 60° von dort nach (4,5|4,330). Der Summenzeiger hat Komponenten (4,5|4,330) cm. A = √(2²+5²+2·2·5 cos60°) cm = √39 cm = 6,245 cm. δ = atan2(5 sin60°, 2+5 cos60°) = 43,9° = 0,766 rad. ω = 2π·50 s⁻¹ = 100π s⁻¹; s(t) = 6,245 cm · sin(100πt/s + 0,766).'),
 schw_reagenz_abitur:P('a) ω = √(g/h) = √(9,81/0,110) s⁻¹ = 9,444 s⁻¹. T = 2π/ω = 0,6653 s und f = 1,503 Hz. b) Nach oben positiv: s(t) = −0,040 m · cos(9,444t/s). Für zwei Perioden: (t;s) = (0;−4 cm), (0,1663;0), (0,3327;+4 cm), (0,4990;0), (0,6653;−4 cm), danach Wiederholung bis 1,3307 s.')+P('c) v(t) = 0,3777 m/s · sin(9,444t/s); a(t) = 3,567 m/s² · cos(9,444t/s). Somit |v|<sub>max</sub> = 0,378 m/s und |a|<sub>max</sub> = 3,57 m/s². d) In 0 ≤ t ≤ 1 s liegen Geschwindigkeitsbetragsmaxima bei 0,1663; 0,4990; 0,8317 s; Beschleunigungsbetragsmaxima bei 0; 0,3327; 0,6653; 0,9980 s. e) a(0,55 s) = 3,567 cos(5,194) m/s² ≈ +1,65 m/s², also nach oben. f) v(0,55 s) ≈ −0,335 m/s: Das Glas bewegt sich nach unten und wird nach oben abgebremst.'),
 schw_essay:answer('Gewählte Systeme: Federpendel und U-Rohr. Beim vertikalen Federpendel gleichen sich Gewichtskraft und Federkraft in der Ruhelage aus. Bei einer Auslenkung ändert sich die Federkraft um Ds und wirkt als F<sub>R</sub> = −Ds zurück. Seine Richtgröße ist D und seine schwingende Masse m. Daher gilt T = 2π√(m/D). Vierfache Masse verdoppelt T, vierfache Federkonstante halbiert T. Das Modell setzt eine leichte lineare Feder und geringe Dämpfung voraus. Im U-Rohr befinden sich beide Flüssigkeitsoberflächen in der Ruhelage auf derselben Höhe. Bei einer Verschiebung s entsteht eine Höhendifferenz 2s und F<sub>R</sub> = −2ρAgs. Richtgröße und schwingende Masse lauten D* = 2ρAg und m = ρAl. Damit folgt T = 2π√(l/(2g)); Dichte und Querschnitt kürzen sich. Das Modell verlangt überall gleichen Querschnitt und vernachlässigbare Reibung. Beide Systeme sind harmonisch wegen ihrer linearen Rückstellkraft, aber nur beim Federpendel verändert eine unabhängig vergrößerte Masse unmittelbar T. Transferfrage: Was passiert bei vierfacher Flüssigkeitslänge? Lösung: Die schwingende Masse vervierfacht sich bei gleicher Richtgröße, deshalb verdoppelt sich T.')
 },extras:{
 5:[['schw-aufgabe7-wagen','Aufgabe 7: Wagen zwischen zwei Federn',P('D₁+D₂ = m(2π/T)² = 0,60 · (2π/1,00)² N/m = 23,687 N/m. D₂ = 23,687 − 9,50 = 14,187 N/m. Bei doppelter Masse ist T′ = √2 · 1,00 s = 1,414 s. Die konstante Hangabtriebskraft mg sinα verschiebt die Ruhelage um mg sinα/(D₁+D₂); die Ableitung der Rückstellkraft und damit T ändern sich nicht.')],['schw-aufgabe8-kette','Aufgabe 8: Kettenstück',P('Die lineare Massendichte ist μ = m/l. Verschiebt sich die Kette um Δh, werden die beiden Seiten um Δh länger bzw. kürzer; die Massendifferenz ist 2μΔh. Ihre Gewichtsdifferenz wirkt rücktreibend: F<sub>R</sub> = −2μgΔh = −(2mg/l)Δh. D* = 19,62 N/m; T = 2π√(l/(2g)) = 1,099 s. Bei A = 0,10 m folgt v<sub>max</sub> = (2π/T)A = 0,572 m/s. Die Skizze C zeigt die Grenze: Wenn ein Ende die Rolle erreicht oder die untere Schlaufe ihre Geometrie verliert, gilt die lineare Massendifferenz nicht mehr. Eine Auslenkung fast so groß wie die ganze Kettenlänge ist daher nicht mit der Formel beschreibbar.')]],
 6:[['schw-funktionsskizzen','Funktionsparameter: Skizzen über zwei Perioden',P('s₁: A = 5 cm, T = 0,5 s, erste positive Maxima bei 0,125 und 0,625 s; Minima bei 0,375 und 0,875 s; Nulldurchgänge bei 0; 0,25; 0,50; 0,75; 1,00 s. s₂: A = 0,5 cm, T = 1 s, positive Maxima bei 0,25 und 1,25 s; Minima bei 0,75 und 1,75 s; Nulldurchgänge bei 0; 0,5; 1,0; 1,5; 2,0 s.')]]
 }},
 'wellen-book-Eigenschaften.html':{suffix:'kiesel29',answers:{essay_resonanz:answer('Trifft die Frequenz des gesungenen Tons die Eigenfrequenz einer Schwingungsmode des Glases, führt der Schalldruck der Glaswand periodisch Energie zu. Bei geringer Dämpfung und ausreichend großer Lautstärke wächst die Schwingungsamplitude stark. Übersteigen die mechanischen Spannungen die Bruchfestigkeit, kann das Glas zerspringen; das ist eine Resonanzkatastrophe. Gleiche Frequenz allein reicht nicht aus, denn die Energiezufuhr muss groß genug sein, um die Dämpfungsverluste zu überwinden.')},extras:{4:[['eig-lc-parameter','Simulation: Kapazität und Induktivität',P('Bei C = 1,00 µF und L = 5,0 mH gilt T = 2π√(LC) = 0,444 ms und f = 2251 Hz. Verdoppeln von C oder L erhöht T um √2 und senkt f auf f/√2. Zu Beginn ist der Kondensator geladen, I = 0 und E<sub>C</sub> maximal. Nach T/4 sind Q = 0 und |I| sowie E<sub>L</sub> maximal. Nach T/2 ist der Kondensator entgegengesetzt geladen. Die Ladung schwingt zwischen den Platten; Elektronen kreisen nicht als Paket ungebremst dauerhaft um den Kreis.')]]}},
 'wellen-book-Einstieg.html':{suffix:'garderobe86',answers:{essay_laola:answer('Bei der La-Ola stehen Menschen nacheinander auf und setzen sich wieder, während die sichtbare Störung seitlich durch das Stadion läuft. Die Analogie einer Transversalwelle passt, weil die lokale Bewegung senkrecht zur Ausbreitung verläuft und die Menschen ihre Plätze behalten. Energie stammt hier allerdings aus jedem einzelnen Menschen; anders als bei einer passiven Seilwelle wird sie nicht einfach von Sitz zu Sitz mechanisch übertragen.')},extras:{
 2:[['einstieg-heft1','Heftaufschrieb 1: Ausbreitung mechanischer Wellen',P('Eine mechanische Welle braucht einen Träger mit schwingungsfähigen, gekoppelten Teilchen. Ein Erreger lenkt ein Teilchen aus; Kopplungskräfte wirken auf Nachbarn und geben die Störung mit zeitlicher Verzögerung weiter. Die Teilchen schwingen lokal, während Bewegungszustand und Energie wandern. Die Ausbreitungsgeschwindigkeit hängt im betrachteten linearen Modell von Elastizität und Trägheit des Trägers ab. Größere Anregungsamplitude macht die Welle hier nicht schneller.')]],
 3:[['einstieg-heft2','Heftaufschrieb 2: Wellentypen',P('Transversal: Schwingungsrichtung senkrecht zur Ausbreitung, zum Beispiel eine Gitarrensaite. Elektromagnetische Wellen sind ebenfalls transversal; dort schwingen Felder und keine materiellen Teilchen. Longitudinal: Schwingungsrichtung parallel zur Ausbreitung, etwa Schall in Luft oder Längswellen in einer Schraubenfeder. Es entstehen abwechselnd Verdichtungen und Verdünnungen.')]],
 4:[['einstieg-heft3','Heftaufschrieb 3: Fronten, Strahlen und Huygens',P('Eine Wellenfront verbindet benachbarte Punkte gleicher Phase. Der Wellenstrahl steht im homogenen isotropen Medium senkrecht auf der Front und bezeichnet die Ausbreitungsrichtung. Punktquellen erzeugen Kreis- bzw. Kugelfronten; ebene Wellen haben parallele Fronten. Nach Huygens geht von jedem Frontpunkt eine Elementarwelle aus; ihre gemeinsame Einhüllende bildet die nächste Front. Bei einem schmalen Spalt fächert diese Front in den geometrischen Schattenraum auf. Je kleiner die Spaltbreite relativ zu λ, desto stärker die Beugung.')]],
 5:[['einstieg-heft4','Heftaufschrieb 4: Brechungsgesetz',P('sinα/sinβ = c₁/c₂ = n₂/n₁; beide Winkel werden vom Lot aus gemessen. Trifft eine ebene Front schräg auf ein langsameres Medium, beginnt die Elementarwelle am zuerst erreichten Grenzpunkt früher, wächst dort aber langsamer. Die Einhüllende dreht sich; der Strahl bricht zum Lot. Die Frequenz bleibt gleich, λ₂ = c₂/f wird kleiner. Für Luft–Glas mit n₂/n₁ = 1,5 und α = 40° folgt β = arcsin(sin40°/1,5) ≈ 25,4°.')]],
 8:[['einstieg-weiterforschen','Weiterforschen: Vakuum, Seismogramme, Wasser',P('Im Vakuum fehlen die gekoppelten Teilchen zur Übertragung von Schalldruckschwankungen. Seismogramme zeigen Laufzeiten, Reflexionen und Brechungen von P- und S-Wellen; unterschiedliche Geschwindigkeiten und das Fehlen von S-Wellen im flüssigen äußeren Erdkern geben Hinweise auf den Erdaufbau. Beim Übergang von Luft in Wasser ist Licht langsamer: Huygens-Elementarwellen im Wasser haben kleinere Radien, weshalb sich die Front dreht und der Strahl zum Lot gebrochen wird.')]]}},
 'wellen-book-wellenfunktion.html':{suffix:'mosaik38',answers:{
 '4:essay1':answer('Die Wellenfunktion y(x,t) ordnet jedem Ort und Zeitpunkt eine Auslenkung zu. Bei festem x zeigt das t-y-Diagramm die Schwingung eines Teilchens mit Periodendauer T. Bei festem t zeigt das x-y-Diagramm die räumliche Wellenform mit Wellenlänge λ. Für eine rechts laufende harmonische Welle gilt y = A sin(ωt − kx), ω = 2π/T und k = 2π/λ. Die Laufzeit x/c verzögert die Schwingung eines entfernten Teilchens; bei einem erst gestarteten Erreger ist y vor Ankunft der Front null. Es gilt c = λ/T = λf. A misst die maximale lokale Auslenkung und c die Ausbreitung der Phase, nicht die Geschwindigkeit eines Seilteilchens.'),
 '5:essay1':answer('Ich musste zuerst erkennen, dass die linke Achse den Ort und die rechte die Zeit darstellt. Nur im Ortsbild lese ich λ = 1,5 m ab, nur im Zeitbild T = 1,1 s. Durch die Einheiten konnte ich die Diagramme sicher unterscheiden. Danach folgten f = 0,91 Hz und c = λ/T ≈ 1,36 m/s. Die Querbewegung der Seilteilchen darf ich nicht mit der Ausbreitungsgeschwindigkeit verwechseln.'),
 'essay-wf-aufstellen-1':answer('Am Erreger lautet die Bewegung y(0,t) = A sin(ωt). Bis zum Ort x braucht die Störung die Laufzeit x/c. Deshalb besitzt das dortige Teilchen zur Zeit t den Zustand, den der Erreger zur früheren Zeit t − x/c hatte. Einsetzen ergibt y(x,t) = A sin[ω(t − x/c)] = A sin[2π(t/T − x/λ)]. Ein weiter entferntes Publikum hört einen Lautsprecherton entsprechend später als ein nahes Publikum. Das Minus vor x beschreibt die Ausbreitung nach rechts; es verändert weder Amplitude noch Frequenz.'),
 '6:reveal1':P('y(0,t) = 0,020 m sin(4πt/s). Bei t = 2,4 s ist y = 0,020 sin(9,6π) m = −0,01902 m. Die Teilchengeschwindigkeit ist v = ∂y/∂t = 0,080π cos(4πt/s) m/s, also v(2,4 s) = +0,07766 m/s. Der Seilanfang liegt 1,90 cm unter der Ruhelage und bewegt sich nach oben. Seine x-Koordinate bleibt 0; c = 0,20 m/s ist die Ausbreitungsgeschwindigkeit und nicht seine Schnelle.')
 },extras:{
 3:[['wf-heft1','Heftaufschrieb 1: Zwei Darstellungen und Zeichnung',P('Für y(x₀,t) bleibt der Ort fest: horizontale Achse t, vertikale Achse y, Start der Schwingung bei tₐ = x₀/c, danach dieselbe Sinusform wie an der Quelle. Im Beispiel x₀ = 1,05 m und c = 0,30 m/s ist tₐ = 3,50 s; vorher ruht der Punkt. Für y(x,t₀) bleibt die Zeit fest: horizontale Achse x, Front bei x<sub>F</sub> = ct₀ und räumliche Periode λ = cT. Im Beispiel t₀ = 1 s liegen die Front bei 0,30 m und λ bei 0,15 m; von der Front nach links beginnt die Kurve mit einem Berg. Rechts der Front ruht das Seil.')],['wf-heft2','Heftaufschrieb 2: Was wird dargestellt?',P('Das x-y-Diagramm zeigt viele Seilpunkte gleichzeitig und macht λ ablesbar. Das t-y-Diagramm zeigt einen einzigen Seilpunkt nacheinander und macht T ablesbar. Sinusförmiges Aussehen allein unterscheidet diese Darstellungen nicht; die Einheit der horizontalen Achse entscheidet.')]],
 4:[['wf-gummiseil-a','Gummiseil A: Teil a und b',P('λ = cT = 0,20 · 0,50 m = 0,10 m = 10 cm. a) Die Front liegt bei x<sub>F</sub> = 22,5 cm. In 0 ≤ x ≤ 22,5 cm gilt y(x,1,125 s) = 2 cm · cos(2πx/10 cm), danach y = 0. Maxima bei 0; 10; 20 cm, Minima bei 5; 15 cm, Nullen bei 2,5; 7,5; 12,5; 17,5; 22,5 cm. b) B wird nach 25 cm/(20 cm/s) = 1,25 s erreicht. Bis dahin ist y<sub>B</sub> = 0; danach y<sub>B</sub>(t) = 2 cm sin[4π(t−1,25 s)/s]. Maxima liegen bei 1,375; 1,875; 2,375 s, Minima bei 1,625; 2,125 s; bei 2,50 s ist y = 0 mit Bewegung nach unten.')]],
 5:[['wf-heft3','Heftaufschrieb 3: Größen',P('A: maximale Auslenkung in m; y: momentane gerichtete Auslenkung in m; T: Dauer einer vollständigen Schwingung in s; f = 1/T: Schwingungen pro Sekunde in Hz; ω = 2πf: Kreisfrequenz in s⁻¹; λ: räumliche Periode in m; k = 2π/λ: Wellenzahl in m⁻¹; c = λf: Phasengeschwindigkeit in m/s; v = ∂y/∂t: momentane Teilchengeschwindigkeit in m/s. Im linearen nichtdispersiven Modell gibt die Quelle A und f vor, der Träger bestimmt c.')],['wf-parameter-simulation','Simulation: Parameter verändern',P('Ausgangswerte: c = 2,5 m/s, f = 0,40 Hz, λ = 6,25 m. Bei c = 5 m/s und gleichem f wird λ = 12,5 m. Bei f = 0,80 Hz und gleichem c wird λ = 3,125 m. Verdopplung von A ändert λ nicht; sie verdoppelt die maximale Schnelle ωA und vervierfacht im linearen Modell die Energie.')],['wf-externe-seilwelle','LEIFI-Aufgabe: Seilwelle',P('a) Links ist die Momentaufnahme y(x), rechts die zeitliche Schwingung y(t). b) A = 3,0 m, T = 1,1 s, f = 1/T = 0,909 Hz und λ = 1,5 m. c) c = λ/T = 1,364 m/s ≈ 1,4 m/s. d) Das Ortsbild zeigt eine Transversalwelle; Luft überträgt keine elastischen Scherkräfte und gewöhnlicher Schall in Luft ist longitudinal. Außerdem wäre für eine hörbare Luftschallwelle mit c ≈ 343 m/s eine Wellenlänge von 1,5 m mit etwa 229 Hz verbunden, nicht mit den hier gemeinsam dargestellten Werten. <a href="https://www.leifiphysik.de/mechanik/mechanische-wellen/aufgabe/seilwelle">Geprüfte Aufgabenquelle</a>.')]],
 6:[['wf-heft4','Heftaufschrieb 4: Wellenfunktion',P('y(x,t) = A sin[2π(t/T − x/λ)] = A sin[ω(t−x/c)]. A ist die Amplitude, T die zeitliche Periode, λ die räumliche Periode, x der Abstand vom Erreger, t die Zeit und c = λ/T. Für den bei t = 0 gestarteten Erreger gilt die Sinusform erst für t ≥ x/c; vorher y = 0. Das Plus vor x/λ beschreibt dagegen eine nach links laufende Welle.')]]}},
 'wellenoptik-lf.html':{suffix:'klammer57',answers:{wopt_essay:answer('Beim idealen Doppelspalt werden zunächst zwei punktförmige kohärente Quellen betrachtet. Ein realer Einzelspalt hat eine endliche Breite; viele Elementarwellen besitzen unterschiedliche Gangunterschiede und interferieren. Für die Minima gilt b sinα = kλ, während die Nebenmaxima aus der Intensitätsfunktion folgen und nicht exakt in der Mitte der Minima liegen. Die Einzelspaltbeugung moduliert bei realen Doppelspalten zusätzlich die Interferenzstreifen. Im Michelson-Interferometer werden zwei kohärente Teilstrahlen wieder überlagert. Eine Spiegelverschiebung Δx verändert den optischen Gangunterschied um 2Δx. Schon Δx = λ/2 verschiebt das Muster um eine volle Streifenperiode. Bei λ = 633 nm entspricht dies nur 316,5 nm, weshalb sehr kleine Längenänderungen sichtbar werden.')},extras:{}} 
};
const wire=P('a) Bei 400 Hz tritt erstmals ein innerer Knoten in der Drahtmitte auf: zweite Eigenschwingung, f₁ = 200 Hz und λ₂ = L = 0,60 m. c = λ₂f₂ = 240 m/s. Die Formulierung „von 0 auf 100 Hz“ widerspricht der Beobachtung bei 400 Hz; verwendet wird der angegebene Beobachtungswert.')+P('b) Abb. 4a (y = 0) passt bei 600 Hz zu einem Knoten bei x = 20 oder 40 cm. Abb. 4b hat T ≈ 1,67 ms und passt zu 600 Hz außerhalb eines Knotens. Abb. 4c hat T = 2,00 ms und passt zu einer erzwungenen Bewegung bei 500 Hz: Dass 500 Hz keine Eigenfrequenz ist, schließt eine vom Elektromagneten erzwungene Schwingung nicht aus. Ohne Angaben zu Anregungsort und Dämpfung lässt sich deren räumliche Form nicht eindeutig bestimmen. Abb. 4d zeigt eine dauerhafte Auslenkung von 2 mm und passt nicht zur beschriebenen Wechselanregung um y = 0 ohne statische Zusatzkraft.')+P('c) Axel: falsch, die gerade Momentaufnahme kann ein gemeinsamer Nulldurchgang sein. Christoph: falsch begründet, ein einzelner Knoten erklärt nicht die Auslenkung null an allen Orten. Eva: richtig, eine Eigenschwingung kann diesen gemeinsamen Nulldurchgang besitzen. Petra: falsch, in diesem Moment steckt die Schwingungsenergie in der Bewegung, die das Ortsbild nicht zeigt.');
const carrier=P('a) c = 50 cm/5,0 s = 10 cm/s; T = 1/f = 4 s und λ = cT = 40 cm. b) In der Mitte sind die Laufzeiten gleich; die gegenphasigen Quellen liefern jederzeit entgegengesetzte Auslenkungen, vor der Ankunft beider Fronten bleibt die Mitte ebenfalls ruhig.')+P('c) Nach 9 s liegt die linke Front bei 90 cm, die rechte bei 10 cm. 90 cm entsprechen 2,25λ. Mit x in cm gilt in 0 ≤ x &lt; 10: y = −cos(πx/20) cm; in 10 ≤ x ≤ 90: y = −2cos(πx/20) cm; in 90 &lt; x ≤ 100: y = −cos(πx/20) cm. In der Mitte liegt bei x = 50 cm ein Knoten; weitere Nullen liegen bei 10, 30, 70 und 90 cm. Zu genau diesem Zeitpunkt ist jedoch die Teilchengeschwindigkeit an allen Punkten null: Beide Einzelwellen stehen lokal an Umkehrpunkten oder sind gerade noch nicht angekommen. „In Ruhe“ ist nicht gleichbedeutend mit „Auslenkung null“.')+P('d) Die erste positive Bewegung ab 3 s kommt vom rechten Erreger; der Punkt liegt 30 cm von rechts, also x = 70 cm von links. Bis 3 s ruht er, von 3 bis 7 s gilt y = 1 cm sin[π(t−3 s)/(2 s)]. Ab 7 s löscht die von links ankommende gegenphasige Welle die Bewegung aus. e) Bei gleichphasigen Quellen gilt für denselben Punkt: y = 0 bis 3 s; y = 1 cm sin[π(t−3 s)/(2 s)] für 3 ≤ t &lt; 7 s; y = 2 cm sin[π(t−3 s)/(2 s)] für 7 ≤ t ≤ 10 s. Maxima: (4 s;1 cm), (8 s;2 cm); Minimum: (6 s;−1 cm), Endwert (10 s;−2 cm).');
const basin=P('a) AQ = √(48²+36²) cm = 60 cm, BQ = 48−36 = 12 cm. Δs = 48 cm, λ = c/f = 32 cm; damit Δs = 1,5λ. b) Die B-Welle erreicht Q nach 0,375 s, die A-Welle nach 1,875 s. Für 0 ≤ t &lt; 0,375 s gilt y = 0; für 0,375 ≤ t &lt; 1,875 s gilt y = −1 mm sin[2π(t−0,375 s)/s]; ab 1,875 s gilt y = 0 durch vollständige Auslöschung. Zeichnungspunkte: (0,375 s;0), (0,625 s;−1 mm), (0,875 s;0), (1,125 s;+1 mm), (1,375 s;0), (1,625 s;−1 mm), (1,875 s;0), danach waagrecht bis 2,5 s. Im mittleren Zeitabschnitt stammt die beobachtete Schwingung von B, nicht von A.');
const combined=P('a) λ = 4 cm, T = 0,40 s, c = 10 cm/s. Nach 0,10 s ist die fortschreitende Welle um 1 cm nach rechts verschoben: y = −1 cm cos(πx/2 cm). b) Für die stehende Welle y = 1 cm sin(πx/2 cm) cos(2πt/0,40 s) gilt nach T/4: y = 0 überall. c) Die beiden Profile stimmen erstmals nach T/2 = 0,20 s wieder überein. d) Beide sind dann y = −1 cm sin(πx/2 cm), also das negative Anfangsprofil; Minima bei 1 und 5 cm, Maxima bei 3 und 7 cm, Nullen bei 0, 2, 4, 6 und 8 cm.')+P('e) Gleichphasig: A liegt auf der Mittelsenkrechten, Δs = 0 und Gesamtamplitude 2 mm. Für B beträgt Δs = √(6²+8²)−8 = 2 cm = λ/2; für C beträgt Δs = 6 cm = 3λ/2. Daher A<sub>B</sub> = A<sub>C</sub> = 0. f) Gegenphasig vertauschen sich Maxima und Minima: A<sub>A</sub> = 0, A<sub>B</sub> = A<sub>C</sub> = 2 mm.')+P('g) Gegenphasige Quellen im Abstand 8 cm erzeugen Maxima bei |Δs| = 2 cm oder 6 cm, nicht bei Δs = 0, 4 oder 8 cm. Auf dem Kreis r = 10 cm ist jedes dieser beiden Betragsniveaus in jedem der vier Quadranten einmal vertreten. Es gibt somit acht Punkte maximaler Amplitude. Für einen Winkel θ zur Quellenverbindung gilt Δs = √(116+80cosθ)−√(116−80cosθ) cm; Maxima liegen ungefähr bei θ = 75,5° und 38,4° sowie den Spiegelungen dieser Winkel.');
files['wellen-book-Interferenz.html']={suffix:'teekanne47',answers:{
 'essay-int-sim-max-min':answer('Bei f = 1,1 ist y(E) = 0 ein Maximum mit Δs/λ = 0. Das erste Minimum liegt mit dem ganzzahligen Regler ungefähr bei y(E) = 123 und Δs/λ = 0,499. Bei f = 2,6 ist das zentrale Maximum weiter bei y(E) = 0 mit Δs/λ = 0, während das erste Minimum etwa bei y(E) = 51 und Δs/λ = 0,503 liegt. Die Cursorwerte sind Simulationskoordinaten, keine Meterangaben. Bei konstantem c verkleinert eine größere Frequenz die Wellenlänge; deshalb rücken die Maxima und Minima näher zur Mitte. Da der Cursor nur ganzzahlige Schritte zulässt, ist ein Minimum meist nur nahezu null.'),
 'essay-int-4':answer('Ich überlagere beide Lichtstrahlen auf einem Schirm und passe ihre Polarisationen sowie ihre Intensitäten an. Ich variiere den Gangunterschied und beobachte, ob helle und dunkle Streifen über die Messzeit ortsfest bleiben. Ein dauerhaft kontrastreiches Muster zeigt eine stabile relative Phase und damit Kohärenz innerhalb der Messdauer und Kohärenzlänge. Gleiche Farbe allein reicht nicht: Zwei unabhängige Lampen haben zufällige Phasenschwankungen. Bleibt ein Muster aus, prüfe ich zunächst Ausrichtung, Polarisation, Helligkeit und Gangunterschied; sein Fehlen beweist unter ungeprüften Bedingungen noch keine Inkohärenz.'),
 'essay-int-1':answer('Im Fernfeld sind die Strahlen zum Beobachtungspunkt nahezu parallel. Die Projektion des Quellenabstands d in Strahlrichtung ergibt Δs ≈ d sinα. Der Schirm liefert tanα = a/e. Wenn |a| ≪ e, ist α klein und sinα ≈ tanα. Einsetzen führt zu Δs ≈ da/e. Die Fernfeldannahme e ≫ d ersetzt dabei nicht die zusätzliche Kleinwinkelannahme |a| ≪ e.'),
 'essay-int-berechnung-1':answer('Der Abstand benachbarter Maxima beträgt näherungsweise Δa = eλ/d. Doppelter Schirmabstand verdoppelt ihn. Doppelter Quellenabstand halbiert ihn. Doppelte Wellenlänge verdoppelt ihn; bei konstantem c erreicht man das durch Halbieren der Frequenz. Gleiche Intensität ist für die Streifenlage nicht nötig, beeinflusst aber den Kontrast. Für große Winkel sind die Schirmabstände nicht mehr gleichmäßig.'),
 'essay-int-bedingungen-1':answer('Ich wähle λ = 600 nm, d = 0,50 mm und e = 2,0 m. Für das erste Maximum gilt Δs = λ und a₁ ≈ eλ/d = 2,4 mm. Für das erste Minimum gilt |Δs| = λ/2 und |a| ≈ 1,2 mm. Weil |a|/e ≈ 0,0012, ist die Kleinwinkelnäherung gut. Die fernfeldgenaue Winkelbeziehung liefert a₁ = e tan(arcsin(λ/d)), praktisch denselben Wert. Die wirklich exakte Geometrie endlicher Punktquellen benutzt hingegen die Differenz der beiden Wurzeln √(e²+(a+d/2)²) − √(e²+(a−d/2)²).'),
 '8:reveal-grundschwingung-1':wire,'9:reveal-grundschwingung-1':carrier,'10:reveal-grundschwingung-1':basin,'11:reveal-grundschwingung-2':combined,
 'reveal-minima-maxima':P('Für gleichphasige Quellen: Maxima Δs = mλ, sinα = mλ/d und a ≈ emλ/d, m ∈ ℤ. Die beidseitigen Minima werden sauber als |Δs| = (j−½)λ, j = 1,2,… beschrieben: sin|α| = (j−½)λ/d und |a| ≈ e(j−½)λ/d. Das erste Minimum liegt also beidseits bei |a| ≈ eλ/(2d); negative Ordnungen dürfen nicht mit derselben unsymmetrischen Schreibweise k−½ durchnummeriert werden.'),
 'reveal-bild-d':combined
},extras:{2:[['int-heft1','Heftaufschrieb 1: Interferenz',P('Bei der Superposition addieren sich die momentanen gerichteten Auslenkungen y = y₁+y₂. Gleichphasige Beiträge verstärken sich, gegenphasige schwächen sich; gleiche Amplituden können sich vollständig auslöschen. Dieses Interferenzprinzip gilt für mechanische, elektromagnetische und Materiewellen. Bei Licht zeigen Intensitätsmaxima helle und Intensitätsminima dunkle Streifen; ein stabiles Muster setzt eine stabile relative Phase voraus.')]],3:[['int-heft2','Heftaufschrieb 2: Konstruktiv und destruktiv',P('Für zwei gleichphasige Quellen gleicher Frequenz gilt Δφ = 2πΔs/λ. Bei Δs = mλ kommen die Wellen gleichphasig an: Gesamtamplitude 2A. Bei |Δs| = (j−½)λ kommen sie gegenphasig an: Gesamtamplitude 0 für gleiche Einzelamplituden. Allgemein ist A<sub>ges</sub> = 2A|cos(πΔs/λ)|. Bei ungleichen Einzelamplituden bleibt selbst am Minimum eine Restamplitude |A₁−A₂|.')]],5:[['int-heft3','Heftaufschrieb 3: Schirmformel und Skizze',P('Die Quellen S₁ und S₂ liegen im Abstand d übereinander. Ihre Mitte M hat horizontalen Abstand e zum Schirm; E liegt dort um a über der Mitte. ME bildet mit der Horizontalen den Winkel α. Die Wege S₁E und S₂E unterscheiden sich um Δs. Im Fernfeld Δs ≈ d sinα; am Schirm tanα = a/e, bei kleinen Winkeln also Δs ≈ da/e.')]],8:[['int-eisendraht','Eisendraht: vollständige Lösung a–c',wire]],9:[['int-traeger2','Wellenträger 2: vollständige Lösung a–e',carrier]],10:[['int-wasserbecken','Wasserbecken: vollständige Lösung a und b',basin]],11:[['int-kombination','Wellenträger und Wasserbecken: vollständige Lösung a–g',combined]]}};
files['wellen-book-Interferenz2.html']={suffix:'briefmarke93',answers:{
 'essay-ds-whichway-compare':answer('Nur Spalt A bzw. nur Spalt B erzeugt je eine breite, glatte Einzelverteilung mit einem Maximum; beide sind gegeneinander verschoben. Mit Welcher-Weg-Markierung ist die Gesamtverteilung c die Summe a+b und bleibt eine breite glatte Verteilung ohne regelmäßige dunkle Interferenzlücken. Ohne Markierung zeigt c unter dieser Hüllkurve viele helle und dunkle Streifen. Die Modellkurve der Simulation enthält im gesamten normierten Bereich −1 bis +1 formal 27 Streifenmaxima und 26 innere Minima; am Rand sind sie sehr schwach. Im groben Histogramm sind weniger getrennte Streifen auflösbar, und bei wenigen Teilchen schwankt ihre sichtbare Zahl. Beim Umschalten ändert sich unmittelbar die vorgegebene Wahrscheinlichkeitskurve; bereits registrierte Treffer können das neue Muster erst nach Zurücksetzen oder durch weitere Treffer widerspiegeln. Einzelne Detektionen bleiben punktförmig. Die Wellenbeschreibung betrifft die Verteilung der Wahrscheinlichkeiten, nicht eine Aufteilung eines Elektrons in zwei halbe Treffer.'),
 'essay-ds-1':answer('Wenn die beiden Wege mit unterscheidbaren Zuständen eines Detektors oder der Polarisation verknüpft sind, verschwindet der Interferenzterm bei einer Messung ohne Unterscheidung dieser Zustände. Die Trefferverteilung ist dann die Summe der beiden Einzelverteilungen. Es genügt eine physikalisch vorhandene Wegmarkierung; ein Mensch muss sie nicht ansehen. Ein Quantenradierer misst die Markierung in einer Basis, die keine Wegzuordnung erlaubt. In passend ausgewählten Teilmengen können Interferenz und ein dazu versetztes Gegenmuster sichtbar werden. Ihre unselektierte Summe zeigt weiterhin keine Streifen. Das Verfahren ändert keine bereits geschehene Messung rückwirkend.'),
 'essay-int2-1':answer('Die beiden beleuchteten Spalte wirken wie kohärente Quellen derselben Ausgangswelle. Am Schirm addieren sich ihre Feldamplituden; die gemessene Intensität ist proportional zum Quadrat der resultierenden Amplitude. Für gleichphasige Spalte liegen Maxima bei d sinα = mλ und Minima bei |d sinα| = (j−½)λ. Bei kleinen Winkeln beträgt der Abstand benachbarter Maxima Δa ≈ eλ/d. Ein Laser-Doppelspalt zeigt deshalb regelmäßig helle und dunkle Streifen. Eine endliche Spaltbreite b fügt die Einzelspalt-Hüllkurve hinzu und schwächt äußere Maxima ab.'),
 'essay-gitter-1':answer('Für die Hauptmaxima gilt sinα<sub>m</sub> = mλ/g. Wird g kleiner, liegen die zulässigen Hauptmaxima weiter außen; hohe Ordnungen können verschwinden, wenn |mλ/g| &gt; 1. Eine größere Spaltzahl N verändert ihre Mittellage nicht, macht sie aber schmaler. In der normierten Koordinate u liegen die nächsten Nullstellen um etwa ±1/N neben einem Hauptmaximum. Bei gleicher Amplitude je Spalt wächst die unnormierte Spitzenintensität wie N²; die Simulation normalisiert sie, sodass diese Zunahme nicht als höherer Spitzenwert erscheint. Zwischen benachbarten Hauptmaxima gibt es N−1 Minima und N−2 Nebenmaxima. Die unveränderte Spaltbreite bestimmt weiterhin die Hüllkurve.'),
 'essay-missing-sim-1':P('Allgemeine Bedingung: m = p·g/b mit ganzzahligem m und p ≠ 0. Für λ = 0,50 µm: m = 2 fehlt zum Beispiel bei g = 4,0 µm, b = 2,0 µm, g/b = 2 und p = 1; sinα = 0,25, α = 14,48°. m = 3 fehlt bei g = 3,0 µm, b = 1,0 µm, g/b = 3 und p = 1; sinα = 0,50, α = 30°.')+P('Das geforderte fehlende erste Maximum ist bei getrennten Spalten mit 0 &lt; b &lt; g unmöglich: m = 1 würde p = b/g &lt; 1 verlangen, aber p muss eine positive ganze Zahl sein. Der mathematische Grenzfall g = b = 2,0 µm, λ = 0,50 µm, p = 1 liefert m = 1 und α = 14,48°. Dann grenzen die Öffnungen ohne Stege aneinander; es ist kein physisch getrenntes Gitter mehr. Falls die Simulation b &lt; g erzwingt, lässt sich dieser Grenzfall nicht einstellen. Das ist eine Grenze der Aufgabenstellung, kein fehlendes Beispiel.'),
 'essay-missing-1':answer('Bei konstantem g bleiben die Positionen der Gitterhauptmaxima sinα = mλ/g gleich. Größeres b verschiebt die Einzelspaltminima sinα = pλ/b zur Mitte und verengt die Hüllkurve. Daher werden äußere Hauptmaxima schwächer oder fallen ganz weg. Eine Ordnung fehlt genau, wenn m = p·g/b ganzzahlig ist. Beispiel: Bei g = 6 µm und b = 1 µm fehlen m = 6,12,…; bei b = 2 µm fehlen m = 3,6,9,… . Für nichtganzzahlige Verhältnisse kann die erste fehlende Ordnung weiter außen liegen, etwa m = 9 für g/b = 4,5 und p = 2.'),
 'essay-thinfilm-1':answer('Ich kontrolliere Schichtdicke d, Brechungsindex n, Einfallswinkel und die Brechungsindices von Umgebung und Träger. Der optische Gangunterschied lautet 2nd cosβ; zusätzlich zählen die relativen Phasensprünge an beiden Reflexionen. Bei Luft–Schicht–Glas mit steigenden Indices treten zwei π-Sprünge auf, deren Differenz null ist; Auslöschung verlangt dann 2nd = λ/2, also eine Viertelwellenschicht. Für vollständige Auslöschung müssen auch die reflektierten Amplituden gleich sein, wozu ideal n<sub>Schicht</sub>² = n<sub>Luft</sub>n<sub>Glas</sub> gilt. Eine Schicht optimiert nur eine Wellenlänge und einen Winkel, während weißes Licht viele Wellenlängen enthält. Schräger Einfall verändert den Gangunterschied und die amplitudenbestimmenden Reflexionskoeffizienten. Überschreitet die Wegdifferenz die Kohärenzlänge, nimmt der Interferenzkontrast ab. Mehrschichtsysteme können einen größeren Bereich entspiegeln, aber eine einzelne Schicht entfernt nicht alle Reflexe.'),
 'reveal-es-kleinwinkel-1':P('Für kleine Winkel α im Bogenmaß gilt sinα ≈ tanα ≈ α. Entscheidend ist |a| ≪ e, denn tanα = a/e. e ≫ Spaltbreite allein garantiert diese Näherung nicht. Für die Minima folgt |a<sub>k</sub>| ≈ ekλ/b.'),
 'reveal-thinfilm-1':P('Interferenz verlangt kohärente Teilstrahlen, keine Beugung. Reflexion an Vorder- und Rückseite einer Schicht erzeugt zwei solche Strahlen mit optischem Gangunterschied 2nd cosβ. Deren relative Reflexionsphase entscheidet zusammen mit diesem Wegunterschied über Verstärkung und Auslöschung.')
},extras:{
 3:[['ds-heft1','Heftaufschrieb 1: Teilchen und Wellen',P('Klassische Tennisbälle liefern bei beiden offenen Spalten die Summe der Trefferverteilungen der einzelnen Spalte. Bei kohärenten Wellen werden zuerst Amplituden addiert; das anschließende Quadrat enthält einen Interferenzterm. Quantenobjekte werden einzeln lokalisiert registriert, ihre vielen Treffer folgen bei unmarkierten Wegen einer interferierenden Wahrscheinlichkeitsverteilung. Bei unterscheidbaren Wegmarkierungen entfällt dieser Term in der unselektierten Statistik.')],['ds-heft2','Heftaufschrieb 2: Muster',P('Klassische Teilchen: zwei überlappende breite Verteilungen ohne regelmäßige dunkle Lücken; c = a+b. Kohärente Quantenobjekte: zentrale helle Zone und beidseits abwechselnde schmale Maxima und Minima unter einer breiten Hüllkurve. Ein einzelner Treffer ist ein Punkt; erst viele Treffer machen das Muster sichtbar.')]],
 4:[['ds-geometrie','Geometrie und Parametervariation',P('α liegt zwischen der Mittelsenkrechten der Spalte und ME. e ist der senkrechte Abstand Spaltebene–Schirm, a die seitliche Schirmposition, d der Mitte-Mitte-Abstand der Spalte. Die Wege S₁E und S₂E erzeugen Δs. Im Fernfeld Δs ≈ d sinα. Größeres d verkleinert den Streifenabstand, größere λ vergrößert ihn. Größeres b verengt die Hüllkurve, ändert aber bei gleichbleibendem d die idealen Interferenzordnungen nicht.')]],
 5:[['ds-zwei-sender','Zwei Sender: a–c',P('a) sinα₁ = 3/15 = 0,20, α₁ = ±11,54°; sinα₂ = 6/15 = 0,40, α₂ = ±23,58°. b) Die m-te Maximarichtung besitzt Δs = mλ; größere Ordnung liegt weiter außen. c) Beim Bewegen des Detektors variiert Δs. Bei |Δs| = (j−½)λ kommen die Wellen gegenphasig an; bei gleichen Amplituden sinkt die Intensität auf null.')],['ds-wellenlaengenmessung','Doppelspalt und Wellenlängenmessung: a–c',P('a) Die beiden kohärenten Teilstrahlen verstärken sich bei Δs = mλ und löschen sich bei ungeraden halben λ aus. b) Δa ≈ Lλ/d = 2,0 · 650·10⁻⁹ / (0,5·10⁻³) m = 2,60 mm. c) λ ≈ Δa·d/L = 4,0·10⁻³ · 0,5·10⁻³ / 2,0 m = 1,00·10⁻⁶ m = 1000 nm. Das ist nahes Infrarot und daher nicht sichtbar.')],['ds-heft3','Heftaufschrieb 3: Doppelspaltformeln',P('Gleichphasige schmale Spalte: Maxima d sinα = mλ, m = 0,±1,…; Minima |d sinα| = (j−½)λ, j = 1,2,… . Auf dem Schirm a = e tanα, kleinwinklig a<sub>m</sub> ≈ emλ/d und |a<sub>min,j</sub>| ≈ e(j−½)λ/d. Aus benachbarten Maxima λ ≈ dΔa/e. Ohne Kleinwinkelnäherung, aber weiterhin im Fernfeld, λ = (d/m) sin(arctan(a<sub>m</sub>/e)).')]],
 7:[['es-simulation','Einzelspalt und Doppelspalt: Experimentieraufträge',P('Bei λ = 633 nm, b = 0,020 mm und e = 2,5 m liegt das erste Einzelspaltminimum bei α ≈ ±1,814° bzw. a ≈ ±7,92 cm. Halbiertes b verdoppelt ungefähr die Breite des Zentralmaximums; größere λ verschiebt die Minima nach außen. Beispiel: Bei b = 0,010 mm ist α₁ ≈ 3,63°. Für den Doppelspalt mit g = 0,100 mm und b = 0,020 mm gilt g/b = 5; jedes fünfte Interferenzmaximum wird von einem Hüllkurvenminimum ausgelöscht. Größeres g macht die feinen Streifen enger; kleineres b verbreitert die Hüllkurve.')],['es-heft4','Heftaufschrieb 4: Beugung am Einzelspalt',P('Die endliche Spaltbreite enthält viele Elementarquellen. Ihre Teilwellen haben in einer schrägen Beobachtungsrichtung unterschiedliche Wege. Bei b sinα = λ lassen sich je ein Beitrag aus der oberen und unteren Hälfte mit Wegdifferenz λ/2 paaren; alle Paare löschen sich aus. Weitere Minima folgen bei ganzzahligem Vielfachen λ über den ganzen Spalt. Das zentrale Maximum reicht von −λ/b bis +λ/b in sinα und ist besonders breit.')],['es-heft5','Heftaufschrieb 5: Einzelspaltformeln',P('Minima: b sinα<sub>k</sub> = ±kλ, k = 1,2,…; kleinwinklig |a<sub>k</sub>| ≈ ekλ/b. Zentralmaximum: α = 0. Nebenmaxima: Mit β = πb sinα/λ löst man tanβ = β, β ≠ 0. Die ersten positiven Lösungen sind β ≈ 4,493; 7,725; 10,904. Daraus b sinα/λ ≈ 1,430; 2,459; 3,471. Die oft benutzten Werte 1,5; 2,5; 3,5 sind nur Näherungen, keine exakten Maximalbedingungen. I = I₀(sinβ/β)².')]],
 8:[['gitter-zeigermodell','Zeigermodell und Spaltzahl',P('Für N = 3 liegen Hauptmaxima bei u = 0 und 1, Minima bei u = 1/3 und 2/3, ein Nebenmaximum bei u = 1/2. Bei u = 0,18 besitzt die normierte Amplitude |sin(3πu)/(3sinπu)| ≈ 0,617. Für N = 10 und dasselbe u ist sie etwa 0,110. Allgemein liegen Minima bei u = q/N, soweit u nicht ganzzahlig ist. Erhöhung von N von 3 auf 10 erhöht zwischen zwei Hauptmaxima die Minimaanzahl von 2 auf 9 und die Nebenmaximaanzahl von 1 auf 8; Hauptmaxima bleiben bei ganzzahligem u.')]],
 10:[['schicht-versuch','Dünne Schicht: Beobachtung und Auswertung',P('Bei einer ausreichend dünnen transparenten Schicht können einzelne Farben je nach Dicke und Blickwinkel verstärkt oder abgeschwächt erscheinen. Eine gleichmäßig dicke Schicht erzeugt nicht zwingend sichtbare Streifen; dafür muss die optische Dicke seitlich variieren, etwa in einem Keil. Ein gewöhnliches Display kann außerdem Spiegelreflexe, Pixel- oder Polarisationsstrukturen zeigen, die kein Nachweis von Dünnschichtinterferenz sind. Bei genau einem relativen π-Sprung gilt in Reflexion: Minima 2nd cosβ = kλ, Maxima 2nd cosβ = (k+½)λ. Bei null oder zwei relativen Sprüngen vertauschen sich diese Bedingungen. <a href="https://openstax.org/books/university-physics-volume-3/pages/3-4-interference-in-thin-films">Physikalische Bedingungen</a>.')]]}};
const modes=P('n bezeichnet hier die Nummer der Eigenschwingung, n = 1 die Grundschwingung. Bei fest/fest gilt λ<sub>n</sub> = 2L/n, f<sub>n</sub> = nc/(2L), n+1 Knoten einschließlich der Enden und n Bäuche. Bei lose/lose gilt dieselbe Frequenz- und Wellenlängenfolge; es gibt n Knoten und n+1 Bäuche einschließlich der Enden. Bei fest/lose gilt λ<sub>n</sub> = 4L/(2n−1), f<sub>n</sub> = (2n−1)c/(4L), n Knoten und n Bäuche. Die n-te Oberschwingung ist dagegen die (n+1)-te Eigenschwingung.')+P('Für fest/fest n = 2: Knoten x = 0, L/2, L; Bäuche L/4 und 3L/4. Für fest/fest n = 3: Knoten 0, L/3, 2L/3, L; Bäuche L/6, L/2, 5L/6. Für fest/lose n = 3: Knoten 0, 2L/5, 4L/5; Bäuche L/5, 3L/5, L. Für lose/lose n = 2: Bäuche 0, L/2, L, Knoten L/4 und 3L/4. Für lose/lose n = 3: Bäuche 0, L/3, 2L/3, L, Knoten L/6, L/2, 5L/6. Benachbarte Knoten oder Bäuche sind λ/2 entfernt; Knoten und nächster Bauch λ/4.')+P('Bei maximaler Auslenkung sind alle beweglichen Punkte momentan ohne Geschwindigkeit, benachbarte Bäuche zeigen in entgegengesetzte Richtungen. Eine Viertelperiode später liegt das ganze Seil auf der Ruhelage, aber die Geschwindigkeiten sind außerhalb der Knoten maximal. Randbedingungen und dauerhafte Knoten bleiben in beiden Momenten dieselben.');
const rubber=P('a) Beim Erhöhen der Frequenz treten an den Eigenfrequenzen große resonante Schwingungsamplituden mit ortsfesten Knoten und Bäuchen auf. Bei fest/fest sind die Eigenfrequenzen ganzzahlige Vielfache der Grundfrequenz; zwischen ihnen kann das Seil erzwungen schwingen, aber ohne eine reine freie Eigenschwingung. b) Das Materialbild zeigt vier Bäuche, also n = 4. Zwei zusätzliche Bäuche bei +20 Hz bedeuten Δn = 2 und f₁ = 20 Hz/2 = 10 Hz. c = 2Lf₁ = 2 · 0,80 m · 10 Hz = 16 m/s. Die abgebildete Mode hat f₄ = 40 Hz, λ₄ = 0,40 m. c) Beim Anzupfen in der Mitte kann die Grundschwingung mit 10 Hz angeregt werden. Gerade Moden haben in der Mitte einen Knoten und werden durch ideales mittiges Zupfen nicht angeregt.');
files['wellen-book-stehende-Welle.html']={suffix:'schublade61',answers:{
 'essay-reflexion-festes-ende-stop':answer('Der einlaufende positive Impuls trifft das feste Ende. Der zurücklaufende Impuls ist an der Wand räumlich gespiegelt und zugleich im Vorzeichen umgekehrt: Aus dem Berg wird ein Tal. Am Endpunkt sind einlaufende und reflektierte Auslenkung gleich groß und entgegengesetzt, deshalb bleibt er immer bei y = 0. In der Umgebung kann sich während der Überlagerung eine kleinere Gesamtauslenkung ergeben.'),
 'essay-reflexion-loses-ende-stop':answer('Der zurücklaufende Impuls ist räumlich an der Wand gespiegelt, aber nicht im Vorzeichen umgekehrt. Ein Berg bleibt ein Berg; es gibt keinen Phasensprung. Im Überlagerungsmoment addieren sich beide Auslenkungen am freien Ende bis zum doppelten Wert des einlaufenden Impulses. Der Endpunkt bewegt sich und bildet bei harmonischer Anregung einen Bauch.'),
 'essay-reflexion-1':answer('Ein an einer Wand festgebundenes Seil reflektiert einen Wellenberg als Tal: π-Phasensprung und Knoten am Ende. Ein ideal reibungsfrei auf einer Führung bewegliches Seilende reflektiert den Berg wieder als Berg: kein Phasensprung und Bauch am Ende. In beiden ideal verlustfreien Fällen ist die reflektierte Amplitude gleich der einlaufenden; nur die Randbedingung und das Vorzeichen unterscheiden sich.'),
 'essay-transmission-1':answer('Bei gleichem Seilzug gilt c = √(F/μ). Dünn nach dicht bedeutet größere lineare Massendichte μ und kleinere Geschwindigkeit. Die reflektierte Welle bleibt im ersten Seil, behält dort f und λ, besitzt eine kleinere Amplitude und einen Phasensprung π. Die transmittierte Welle hat dieselbe Frequenz, aber wegen kleinerem c eine kleinere λ und kleinere Auslenkungsamplitude. Dicht nach dünn liefert eine reflektierte Welle ohne Phasensprung, ebenfalls mit unveränderter λ im Ausgangsmedium. Die transmittierte Auslenkungsamplitude kann größer werden, während λ wegen größerem c wächst. Energie wird dadurch nicht erzeugt: Energiefluss hängt auch von der Wellenimpedanz ab.'),
 'essay-stehend-moden-stop-1':modes,
 'essay-stehend-entstehung-1':answer('Eine ideale stehende Welle ist die Summe zweier gleich starker gegenläufiger Wellen gleicher Frequenz. Deren zeitlich gemittelte Energieflüsse sind gleich groß und entgegengesetzt, sodass kein Nettoenergietransport entlang des Seils erfolgt. Die Wellen heben sich nicht überall auf: Knoten bleiben ruhig, Bäuche schwingen. Energie wechselt weiterhin zwischen kinetischer und elastischer Form und kann sich innerhalb eines Schwingungsabschnitts zeitweise verlagern.'),
 'essay-stehend-1':answer('Bei der Reflexion am losen Ende entsteht y = 2A sin(ωt)cos(kx), am festen Ende y = −2A cos(ωt)sin(kx). Der Ortsfaktor legt die feste Amplitude jedes Punktes fest; die Nullen dieses Faktors sind dauerhaft ruhende Knoten. Der Zeitfaktor bewirkt überall dieselbe Frequenz. Innerhalb eines Abschnitts zwischen zwei Knoten schwingen die Punkte gleichphasig; benachbarte Abschnitte sind um π gegeneinander verschoben. Deshalb ist die pauschale Aussage „alle Punkte phasengleich“ fachlich zu weitgehend. Die Knoten wandern nicht; die resultierende Form läuft nicht wie eine einzelne Welle über das Seil.'),
 'reveal-seil-B':rubber,'reveal-seil-B-2':rubber
},extras:{
 3:[['steh-heft1','Heftaufschrieb 1: Reflexion mit Skizze',P('Festes Ende: ankommender Berg → Wand → zurücklaufendes Tal; y(Wand,t) = 0 und Phasensprung π. Loses Ende: ankommender Berg → bewegliches Ende → zurücklaufender Berg; kein Phasensprung. Bei vollständiger verlustfreier Reflexion ändern sich Betrag der Amplitude, Frequenz und Wellenlänge im selben Medium nicht.')]],
 5:[['steh-heft2','Heftaufschrieb 2: Transmission und Reflexion',P('Transmission ist die in das zweite Medium weiterlaufende Welle; Reflexion ist der in das erste Medium zurücklaufende Anteil. Für Seile mit gleicher Spannung: dünn → dicht: zurücklaufendes Tal, transmittierter kleinerer Berg mit kleinerer λ; dicht → dünn: zurücklaufender kleinerer Berg, transmittierter größerer Berg mit größerer λ. Mit Impedanzen Z₁ und Z₂ gilt für Auslenkungsamplituden r = (Z₁−Z₂)/(Z₁+Z₂), t = 2Z₁/(Z₁+Z₂). Daher ist r beim Übergang zu größerem Z negativ. Die Frequenz bleibt bei allen Anteilen gleich.')]],
 6:[['steh-moden-vollstaendig','Alle Randbedingungen: Momentaufnahmen und Positionen',modes]],
 7:[['steh-heft3','Heftaufschrieb 3: Entstehung und Randbedingungen',P('Gleichfrequente, gleich starke gegenläufige Wellen erzeugen feste Knoten und schwingende Bäuche. Der Abstand benachbarter Knoten beträgt λ/2, der Abstand Knoten–Bauch λ/4. Die zeitlich gemittelten Energieflüsse kompensieren sich. An festen Enden ist die Auslenkung null, an freien Enden ihre Ortsableitung null. Die Grundformen sind bei fest/fest ein Bauch zwischen zwei Endknoten, bei lose/lose ein Knoten zwischen zwei Endbäuchen und bei fest/lose ein Viertelwellenzug vom Endknoten zum Endbauch.')+modes],['steh-gummiseil-c','Gummiseil C: vollständige Lösung a–c',rubber]],
 8:[['steh-spiegelung-lose','Kleine Aufgabe: Reflexion am losen Ende',P('y<sub>r</sub>(x,t) = y<sub>i</sub>(−x,t): Das freie Ende verlangt keine Auslenkung null, sondern eine verschwindende Steigung am Rand. Deshalb wird nur x gespiegelt; das Vorzeichen bleibt erhalten, der Endpunkt kann schwingen.')],['steh-spiegelung-fest','Kleine Aufgabe: Reflexion am festen Ende',P('y<sub>r</sub>(x,t) = −y<sub>i</sub>(−x,t): Die Orts-Spiegelung kehrt die Laufrichtung um. Die zusätzliche Vorzeichenumkehr stellt sicher, dass sich die Auslenkungen am festen Endpunkt jederzeit zu null addieren.')]]}};
files['wellen-simulationen.html']={suffix:'balkon82',answers:{},extras:{
 1:[['sim-feder','Federpendel: Masse und Amplitude',P('Bei m = 0,50 kg, D = 25 N/m und A = 0,20 m gilt T = 0,889 s, E = ½DA² = 0,50 J und v<sub>max</sub> = √(D/m)A = 1,414 m/s. Verdopplung nur der Masse liefert T′ = 1,257 s, gleiche Gesamtenergie und v′<sub>max</sub> = 1,00 m/s. Verdopplung nur der Amplitude bei Ausgangsmasse lässt T gleich, vervierfacht E auf 2,00 J und verdoppelt v<sub>max</sub> auf 2,828 m/s. Werden beide Änderungen nacheinander beibehalten, gelten T = 1,257 s, E = 2,00 J und v<sub>max</sub> = 2,00 m/s. Am Umkehrpunkt sind v = 0 und E<sub>pot</sub> maximal; in der Ruhelage sind |v| und E<sub>kin</sub> maximal.')],['sim-u-rohr','U-Rohr: Dichte und Querschnitt',P('m = ρAl und D* = 2ρgA. In T = 2π√(m/D*) kürzen sich ρ und A: T = 2π√(l/(2g)). Bei l = 0,80 m und g = 9,81 m/s² ist T = 1,269 s, unabhängig von Dichte und Querschnitt im idealen Modell. Doppelte Dichte bzw. doppelter Querschnitt verdoppelt sowohl die Trägheit als auch die Rückstellkraft. Die Oberflächen bewegen sich gegenläufig mit Höhenunterschied 2s.')],['sim-wagen','Wagen: Neigungswinkel',P('D* = D₁+D₂ = 30 N/m und T = 2π√(0,60/30) s = 0,889 s. Der Winkel verändert T nicht. Die Ruhelage verschiebt sich hangabwärts um s₀ = mg sinα/D*. Bei α = 30° ist s₀ = 9,81 cm. Die Schwingungsamplitude ist relativ zu dieser neuen Lage zu messen; nur konstante Federkonstanten, gleiche Masse und vernachlässigte Reibung liefern die unveränderte Periodendauer.')]],
 2:[['sim-pendel','Fadenpendel: 5°, 20° und 50°',P('Die Kleinwinkelnäherung liefert bei l = 1 m T₀ = 2,006 s. Mit dem exakten sinα-Gesetz wird die Periode amplitudenabhängig: ungefähr 2,007 s bei 5°, 2,021 s bei 20° und 2,106 s bei 50°. Bei 5° überdecken sich die Modelle fast; bei 20° wächst über mehrere Perioden eine sichtbare Phasendifferenz; bei 50° beträgt die Periodenabweichung etwa 5 %. Ändern nur der Masse verändert weder die exakte noch die angenäherte Bewegung, weil sich m in der Bewegungsgleichung kürzt.')],['sim-ueberlagerung','Phase und Schwebung',P('Bei gleichen Frequenzen und A₁ = A₂ = 0,60 beträgt die Summenamplitude bei 0°: 1,20; bei 90°: 0,60√2 ≈ 0,849 und die Summenphase 45°; bei 180°: 0. Für f₁ = 1,00 Hz und f₂ = 1,15 Hz gilt f<sub>S</sub> = 0,15 Hz, sodass Lautstärkemaxima im Abstand von 6,67 s wiederkehren. Die schnelle Trägerschwingung besitzt die mittlere Frequenz 1,075 Hz; die signierte Kosinushülle hat halbe Differenzfrequenz, ihr Betrag wiederholt sich mit 0,15 Hz.')]],
 4:[['sim-huygens','Beugung am Spalt',P('Ein engerer Spalt erzeugt hinter der Öffnung eine stärker gekrümmte, fächerförmige Wellenfront; ein breiter Spalt lässt die Mitte näherungsweise eben. Die dünnen Kreise sind Elementarwellen, die kräftige Front ist ihre Einhüllende. Transversal schwingen die Teilchen quer, longitudinal parallel zur Ausbreitung; ihre lokale Bewegung wandert nicht mit der Front.')]],
 9:[['sim-lc','LC-Kreis: Kapazität und Induktivität',P('Ausgangswerte L = 5,0 mH und C = 1,00 µF: T = 2π√(LC) = 0,444 ms und f = 2251 Hz. Vergrößern eines Faktors um 4 verdoppelt T; Vergrößern beider um 4 vervierfacht T. Q und U verlaufen gleichphasig, I ist um eine Viertelperiode verschoben. Bei maximaler Kondensatorladung ruht der Strom; bei Q = 0 sind Strombetrag und magnetische Feldenergie maximal. Die Summe elektrischer und magnetischer Energie bleibt im idealen Modell konstant.')]]}};
files['Akustik-Versuche.html']={suffix:'segeltuch24',answers:{
 ak_essay_schallerzeugung:answer('Gewählter Versuch 1: klingender Strohhalm. Erwartete Beobachtung: Beim Anblasen entsteht ein schnarrender Ton; an den Lippen sind Vibrationen fühlbar. Nach dem Kürzen wird der Ton höher. Erklärung: Die zugeschnittenen Spitzen schwingen wie ein Doppelrohrblatt und regen die Luftsäule an; eine kürzere Luftsäule besitzt höhere Resonanzfrequenzen. Gewählter Versuch 2: Metallstreifen/Lineal. Erwartete Beobachtung: Das freie Ende schwingt nach dem Loslassen auf und ab, der Ton klingt ab. Kürzerer Überstand führt zu schnellerer Bewegung und höherem Ton. Die elastische Biegekraft wirkt rücktreibend, Material- und Luftreibung dämpfen. Diese Angaben beschreiben erwartete Beobachtungen, keine behaupteten eigenen Messungen.'),
 ak_essay_stimmgabel:answer('Gewählte Versuche: tauchende Stimmgabel und Spur auf der Rußplatte. Beim vorsichtigen Eintauchen der schwingenden Zinkenspitzen erwarten wir Spritzer und Wellen; die Stimmgabel klingt schneller ab. Die Zinken übertragen Energie auf das Wasser und werden dadurch gedämpft. Auf der gleichmäßig bewegten Rußplatte erwarten wir eine wellenförmige Spur. Stärkeres Anschlagen vergrößert die seitliche Amplitude und die Lautstärke; bei gleicher Ziehgeschwindigkeit bleibt der Abstand der Wellenberge annähernd gleich, weil die Eigenfrequenz kaum geändert wird. Die mit der Zeit abnehmende Amplitude zeigt Dämpfung.'),
 ak_essay_schall_unterwegs:answer('Gewählter Versuch: Schnurtelefon. Bei gespannter Schnur ist die geflüsterte Botschaft im zweiten Becher deutlich verständlicher als ohne Becher; bei lockerer Schnur wird sie leise oder unverständlich. Die Luft im ersten Becher versetzt den Becherboden in Schwingung. Diese wird auf die gespannte Schnur, den zweiten Becherboden und die Luft am Ohr übertragen. Die gekoppelten Teilchen schwingen lokal; es wandert keine Schnur vom Sprecher zum Zuhörer. Eine frei gespannte Schnur ohne Berührung überträgt besser als eine lockere, angefasste oder an Hindernissen anliegende Schnur. Vergleich der Medien: Hier wirken Luft und Festkörper zusammen; beim Weckerversuch leitet auch das Wasser zwischen Glas und Wannenwand die Schwingung weiter.')
},extras:{
 3:[['ak-material-luftballon','Material: Luftballon',P('Die gespannte Ballonöffnung flattert im ausströmenden Luftstrom und erzeugt einen quietschenden Ton. Größere Spannung erhöht bei ähnlicher Geometrie die Eigenfrequenz und meistens die Tonhöhe. Beim Entleeren ändern sich Druck, Strömung und Öffnungsform, der Klang kann tiefer und leiser werden oder ganz aussetzen. Ohne Kontrolle dieser Größen ist kein streng monotoner Tonhöhenverlauf garantiert. Schwingend sind die beiden Gummilippen der Öffnung; die Luft überträgt deren Druckschwankungen.')],['ak-material-strohhalm','Material: Klingender Strohhalm',P('Erwartet werden ein schnarrender Ton und fühlbare Vibrationen an den Lippen. Die flachgedrückten, spitz zugeschnittenen Halmenden öffnen und schließen sich periodisch; sie regen die Luftsäule im Halm an. Kürzen am freien Ende verkürzt die Luftsäule und erhöht ihre Resonanzfrequenz, der Ton wird höher. Die Halmspitzen und die Luftsäule schwingen gekoppelt.')],['ak-material-metall','Material: Metallstreifen oder Lineal',P('Nach dem Auslenken schwingt das freie Ende um die unverbogene Lage und erzeugt einen abklingenden Ton. Bei kürzerem freien Ende wird die Schwingung schneller, der Ton höher. Eine längere freie Strecke ist biegeweicher und besitzt eine niedrigere Eigenfrequenz. Größere Auslenkung erhöht hauptsächlich Amplitude und Lautstärke, nicht in erster Linie die Tonhöhe.')],['ak-material-frosch','Material: Musikinstrument-Frosch',P('Beim Streichen über die Rillen entsteht ein ratternder, quakender Klang. Jede Rille gibt dem hölzernen Körper einen kurzen Stoß; der Körper und die Luft in seinem Hohlraum schwingen und strahlen Schall ab. Schnelleres Streichen erhöht die Folgefrequenz der Stöße, während die Resonanzen der Bauform die Klangfarbe bestimmen.')],['ak-material-kehlkopf','Material: Kehlkopf',P('Beim Summen sind am Kehlkopf Vibrationen fühlbar. Bei hohen Tönen schwingen die Stimmlippen schneller, bei tiefen langsamer; einzelne Schwingungen sind mit dem Finger nicht auszuzählen. Ausströmende Luft regt die Stimmlippen an, deren Spannung und wirksame Länge die Tonhöhe beeinflussen. Nicht jeder Laut ist stimmhaft: Beim Flüstern oder bei einem stimmlosen „s“ fehlt die regelmäßige Stimmlippenschwingung.')]],
 4:[['ak-material-stimmgabel1','Material: Erfahrungen mit der Stimmgabel',P('Die beiden Zinken schwingen gegenläufig und erzeugen einen Ton. Bei Kontakt des Knopfes mit einem festen Körper ist der Ton oft deutlicher als über Luft allein, weil Schwingungen auf den Körper übertragen werden. Am Zahn fühlt sich dies vibrierend an; über Zähne und Schädelknochen gelangt Körperschall zum Innenohr. Die Frequenz und damit die Tonhöhe bleiben im Wesentlichen gleich. In der Skizze sind Zinken, Stiel und Knopf zu unterscheiden.')],['ak-material-stimmgabel2','Material: Tauchende Stimmgabel',P('Die schwingenden Spitzen stoßen wiederholt gegen das Wasser: Es entstehen Spritzer und Oberflächenwellen. Die Schwingung der Zinken ist damit indirekt sichtbar. Energie wird ins Wasser abgegeben, deshalb klingt die Stimmgabel schneller ab.')],['ak-material-stimmgabel3','Material: Laut und leise beim Drehen',P('Bei gleichbleibendem Abstand wechseln lautere und leisere Richtungen, während die Tonhöhe gleich bleibt. Die gegenläufig schwingenden Zinken strahlen mit richtungsabhängiger Interferenz ab. In manchen Richtungen schwächen sich ihre Schalldruckbeiträge stärker ab als in anderen. Das Drehen ändert die Richtung zum Ohr, nicht die Eigenfrequenz.')],['ak-material-stimmgabel4','Material: Spur auf der Rußplatte',P('Die Spitze zeichnet eine sinusähnliche Spur. Kräftiges Anschlagen erzeugt eine größere Amplitude als schwaches Anschlagen. Bei gleicher Ziehgeschwindigkeit bleiben die Abstände benachbarter Berge nahezu gleich; unterschiedliches Ziehen kann diese Abstände verändern, ohne dass sich die Frequenz ändert. Die abnehmende Spurhöhe zeigt Dämpfung.')]],
 5:[['ak-material-glocke','Material: Glockenläuten',P('Der angeschlagene Löffel schwingt. Mit Schnurkontakt und Fingern am Ohr klingt er deutlich voller und lauter; ohne diese Verbindung hört man hauptsächlich den schwächeren Luftschall. Der Übertragungsweg ist Löffel → gespannte Schnur → Finger/Kopf → Innenohr. Beim Loslassen dieser Kopplung bleibt hauptsächlich Löffel → Luft → Ohr.')],['ak-material-wasser','Material: Schallausbreitung in Flüssigkeiten',P('Der Wecker bleibt trocken im Becherglas. Erwartet wird ein gut hörbares, häufig lauteres Ticken beim Ohrkontakt mit der Wannenwand: Wecker → Glasboden → Wasser → Wannenwand → Ohr. Wasser überträgt Druckschwankungen; Glas und Wannenwand leiten ebenfalls Körperschall. Die Lautstärke hängt von der Kopplung und möglichen Nebenwegen ab; der Versuch allein misst keine Schallgeschwindigkeit und beweist kein universelles „Wasser ist immer lauter“.')],['ak-material-schnurtelefon','Material: Schnurtelefon',P('Die Botschaft ist bei gespannter, frei liegender Schnur besser verständlich als ohne Telefon oder mit lockerer Schnur. Schwingende Luft bewegt den ersten Becherboden, dieser die Schnur, die Schnur den zweiten Boden und dieser die Luft am Ohr. Berühren der Schnur dämpft; Spannung stellt die mechanische Kopplung her. Ein Luftweg bleibt parallel vorhanden, wird bei leiser Stimme aber schwächer gehört.')],['ak-material-kerze','Material: Kerzenflimmern',P('Beim Klopfen auf die Folie zittert oder weicht die Flamme aus. Die bewegte Folie erzeugt einen Druckstoß und Luftbewegung in der Röhre, die sich zur Öffnung fortpflanzen und die Flamme beeinflussen. Bei einem kräftigen Einzelstoß können auch ein Luftstrahl oder Wirbelringe beitragen; der Versuch zeigt deshalb nicht ausschließlich eine reine harmonische Schallwelle.')]],
 6:[['ak-weiterdenken','Weiterdenken: Welcher Versuch zeigt Schall besonders deutlich?',answer('Die tauchende Stimmgabel überzeugt mich besonders: Die Bewegung der Zinken ist mit bloßem Auge klein, aber Spritzer machen ihre Wirkung sichtbar. Gleichzeitig höre ich den Ton. Die Energieübertragung auf das Wasser erklärt das schnellere Abklingen und verbindet damit Hören, Sehen und das Modell eines schwingenden Körpers.')]]}};
files['wellen-book..html']={suffix:'karton68',answers:{},extras:{1:[
 ['63237759-29c2-4d1f-8dce-265eb8c7cdfe','Voraussetzungen für eine mechanische Welle',P('Richtig sind alle vier Bedingungen: ein Medium mit schwingungsfähigen Teilchen, Kopplung zwischen den Teilchen, eine Störung und Energiezufuhr zur Anregung. Ein Vakuum ist kein mechanischer Wellenträger.')],
 ['6001eeda-2873-4805-b35c-01fee44c3140','Was überträgt eine Welle?',P('Im idealisierten mechanischen Wellenmodell werden Bewegungszustand, Energie und gegebenenfalls Impuls übertragen; die Teilchen schwingen um ihre Ruhelagen, ohne dass die Materie mit der Welle dauerhaft mitwandert.')],
 ['6aaea524-1712-4bb5-8622-d40ba3c93278','Energieformen in Wellen',P('Mechanische Wellen enthalten kinetische Energie der bewegten Teilchen und elastische potenzielle Energie ihrer Kopplung. Die Kopplungskräfte übertragen Energie zwischen Nachbarn. Der Energieaustausch eines einzelnen Federpendels darf nicht pauschal mit einer fortschreitenden Seilwelle gleichgesetzt werden: Dort hängen kinetische Energie vom zeitlichen Ableitungsquadrat und elastische Energie vom räumlichen Steigungsquadrat ab; beide können lokal zugleich groß sein.')],
 ['74f84d58-6514-4eb7-8032-81fc66a4b0ea','Lückentext: Mechanische Welle',P('Eine mechanische Welle kann sich nur ausbreiten, wenn ein <strong>Medium</strong> vorhanden ist, in dem <strong>schwingungsfähige Teilchen</strong> sitzen. Diese müssen <strong>gekoppelt</strong> sein, damit sich eine <strong>Störung</strong> weitertransportieren kann. Energie wird übertragen, aber kein <strong>Material</strong>.')],
 ['1b5f03c4-30c0-4b80-8565-7657c2922f9e','Zwischenfazit: Warum gekoppelte Teilchen?',answer('Ein ausgelenktes Teilchen übt über die Kopplung eine Kraft auf seinen Nachbarn aus. Dieser wird beschleunigt und lenkt wiederum das nächste Teilchen aus. Wegen der Trägheit benötigen diese Vorgänge Zeit, sodass die Störung mit endlicher Geschwindigkeit weiterläuft. Dabei wird Energie durch Arbeit der Kopplungskräfte übertragen. Ohne Kopplung würde nur das zuerst angeregte Teilchen schwingen. Ein Vakuum enthält keine solchen Teilchen und trägt daher keine mechanischen Schallwellen.')],
 ['h5p-simulation-parameter','Simulation: Amplitude, Frequenz und Spalte',P('Größere Amplitude bedeutet größere lokale Auslenkungen, nicht größere Ausbreitungsgeschwindigkeit. Bei konstantem c verkleinert größere Frequenz die Wellenlänge λ = c/f. Eine punktförmige Anregung erzeugt Kreiswellen; ein gerader Erreger erzeugt näherungsweise ebene Fronten. Hinter einem schmalen Spalt breitet sich die Welle fächerförmig in den Schattenraum aus; zwei kohärent angeregte Spalte erzeugen Interferenzmaxima und -minima.')],
 ['2384208a-7a0f-4a25-87b1-3c611bb44959','Auswertung der Simulation',answer('Bei einer Punktquelle sehe ich konzentrische Kreisfronten, bei gerader Anregung parallele ebene Fronten. Die Teilchen bewegen sich lokal und wandern nicht mit den Fronten. Höhere Frequenz führt bei gleichbleibender Ausbreitungsgeschwindigkeit zu engeren Frontabständen. Größere Amplitude erhöht deren Auslenkung. Ein schmaler Spalt wirkt annähernd wie eine neue Punktquelle; hinter zwei Spalten bilden sich Bereiche großer und kleiner Gesamtamplitude.')],
 ['h5p-wellentypen-beispiele','Eigene Beispiele zu Wellentypen',P('Transversal: Querbewegung einer Gitarrensaite oder eines Seils; die Bewegung steht senkrecht zur Laufrichtung. Elektromagnetische Wellen sind ebenfalls transversal, hier schwingen Felder. Longitudinal: Schall in Luft oder die längs angeregte Schraubenfeder; Teilchenbewegung parallel zur Ausbreitung, abwechselnde Verdichtung und Verdünnung.')],
 ['53b03b90-7f84-4c35-aa3a-dcac9fe2fa52','Zuordnung: Transversal- und Longitudinalwellen',P('Transversal: „Auslenkung senkrecht zur Ausbreitungsrichtung“, „Bsp: Gitarrensaite, elektromagnetische Welle“, „Teilchen bewegen sich auf- und abwärts“. Longitudinal: „Auslenkung parallel zur Ausbreitung“, „Beispiele: Schallwelle, Federdruck“, „Teilchen bewegen sich vor- und rückwärts“. Die Richtungswörter gelten für die horizontale Ausbreitung in der Abbildung.')],
 ['h5p-tabelle-wellentypen','Aufzeichnungen: Vollständige Vergleichstabelle',`<div class="table-scroll"><table><thead><tr><th>Merkmal</th><th>Transversal</th><th>Longitudinal</th></tr></thead><tbody><tr><td>Teilchenbewegung bei horizontaler Ausbreitung</td><td>Auf und ab</td><td>Vor und zurück</td></tr><tr><td>Auslenkung</td><td>Senkrecht zur Ausbreitung</td><td>Parallel zur Ausbreitung</td></tr><tr><td>Beispiele</td><td>Gitarrensaite; EM-Welle mit schwingenden Feldern</td><td>Schall in Luft; Längswelle in einer Schraubenfeder</td></tr><tr><td>Gemeinsamkeit</td><td colspan="2">Eine Störung breitet sich aus; bei mechanischen Wellen schwingen die gekoppelten Teilchen lokal.</td></tr></tbody></table></div>`]
 ]}};
const {graph,scheme,waveTypes}=require('./.solution-figures.cjs');
files['wellen-book-Einstieg.html'].answers.reveal1=P('Eine nach rechts laufende Welle hat y(x,t₀) = A sin[ω(t₀−x/c)]. Je weiter rechts ein Punkt liegt, desto früher ist der dort dargestellte Erregerzustand. Daher startet die Momentaufnahme am Frontort x = ct₀ mit dem zuerst erzeugten Zustand und wird nach links in zeitlich späterer Reihenfolge gezeichnet. Beim weiterlaufenden Video verschiebt sich das ganze Profil nach rechts; ein einzelner Seilpunkt bewegt sich dagegen nur auf und ab.');
files['wellen-book-Interferenz2.html'].answers['reveal-int2-1']=P('Für |a| ≪ e gilt α ≈ 0 im Bogenmaß und damit sinα ≈ tanα = a/e. Die weitere Annahme e ≫ d erlaubt erst die Fernfeldprojektion Δs ≈ d sinα. Zusammen ergibt sich Δs ≈ da/e. Ein großer Abstand e relativ zu d allein genügt nicht, wenn der Beobachtungspunkt weit seitlich liegt.');
files['wellen-book-Interferenz2.html'].answers['reveal-int2-aufgabe3-loesung']=files['wellen-book-Interferenz2.html'].extras[5][1][2]+P('Aus der Position a<sub>k</sub> eines bestimmten Maximums lautet die fernfeldgenaue Formel λ = (d/k) sin(arctan(a<sub>k</sub>/L)). Ein allgemeiner Abstand Δx zwischen zwei beliebigen benachbarten Maxima darf dort nicht anstelle von a<sub>k</sub> eingesetzt werden.');
files['wellen-book-stehende-Welle.html'].answers['cloze-stehend-aufgabe4-werte']=P('Für die Grundschwingung gilt <strong>λ = c/f</strong>. Mit c = 40 m/s und f = 20 Hz folgt <strong>λ = 2 m</strong>. Für die n-te <strong>Eigenschwingung</strong> nutzt man <strong>f<sub>n</sub> = nf₁</strong>; damit ist <strong>f₂ = 40 Hz</strong> und <strong>f₃ = 60 Hz</strong>. Diese Werte lösen die Modennummerierung der Konfiguration. Die im Aufgabentext wörtlich verlangte zweite und dritte <strong>Oberwelle</strong> sind dagegen dritte und vierte Eigenschwingung, also <strong>60 Hz und 80 Hz</strong>.');
files['wellen-book-stehende-Welle.html'].answers['reveal-stehend-aufgabe4-loesung']=P('a) λ = c/f = 40 m/s / 20 Hz = 2 m. b) Zweite und dritte Oberwelle im üblichen Wortsinn: f = 3f₁ = 60 Hz und f = 4f₁ = 80 Hz. Die Quelle nennt stattdessen die zweite und dritte Eigenschwingung mit 40 und 60 Hz; diese beiden Nummerierungen müssen unterschieden werden. c) Die einlaufende und die gleich starke gegenläufige reflektierte Welle überlagern sich. Am festen Ende erzeugt der π-Sprung einen Knoten; zwischen den Knoten entstehen Bäuche mit maximaler Amplitude 2A.');
files['wellen-book-stehende-Welle.html'].answers['cloze-stehend-1']=P('Die <strong>Primärwelle</strong> regt am Ende eine <strong>Sekundärwelle</strong> an. Beide haben <strong>gleiche Frequenz</strong> und <strong>gleiche Wellenlänge</strong>, laufen aber in <strong>entgegengesetzte Richtungen</strong>. Durch Überlagerung entsteht eine <strong>stehende Welle</strong> mit <strong>doppelter Amplitude</strong> an einem <strong>losen</strong> Ende; am festen Ende ist die Amplitude null.');
const basinGraph=graph({title:'Wasserbecken: Auslenkung von Q',xMax:2.5,yMax:1,yLabel:'y in mm',curves:[{fn:t=>t<.375||t>=1.875?0:-Math.sin(2*Math.PI*(t-.375)),label:'Gesamtauslenkung'}],ticks:[0,.375,.875,1.375,1.875,2.5]});
files['wellen-book-Interferenz.html'].answers['reveal-bild-2']=basin+basinGraph;
files['wellen-book-wellenfunktion.html'].answers['4:reveal-seil-A']=files['wellen-book-wellenfunktion.html'].extras[4][0][2]+graph({title:'Gummiseil A: Momentaufnahme bei 1,125 s',xMax:25,yMax:2,xLabel:'x in cm',curves:[{fn:x=>x>22.5?0:2*Math.cos(2*Math.PI*x/10),label:'Auslenkung'}],ticks:[0,5,10,15,20,22.5,25]});
files['wellen-book-wellenfunktion.html'].answers['reveal-seil-A-2']=graph({title:'Gummiseil A: Schwingung von B',xMax:2.5,yMax:2,curves:[{fn:t=>t<1.25?0:2*Math.sin(4*Math.PI*(t-1.25)),label:'B bei x = 25 cm'}],ticks:[0,.5,1,1.25,1.5,2,2.5]});
files['wellen-book-wellenfunktion.html'].answers['6:reveal-seil-A']=files['wellen-book-wellenfunktion.html'].answers['6:reveal1'];
files['schwingungen.html'].extras[6][0][2]+=graph({title:'s₁: zwei Perioden',xMax:1,yMax:5,yLabel:'s in cm',curves:[{fn:t=>5*Math.sin(4*Math.PI*t),label:'A = 5 cm, T = 0,5 s'}]})+graph({title:'s₂: zwei Perioden',xMax:2,yMax:.5,yLabel:'s in cm',curves:[{fn:t=>.5*Math.sin(2*Math.PI*t),label:'A = 0,5 cm, T = 1 s'}]});
files['schwingungen.html'].answers.schw_reagenz_abitur+=graph({title:'Reagenzglas: zwei Perioden, oben positiv',xMax:4*Math.PI/Math.sqrt(9.81/.11),yMax:4,yLabel:'s in cm',curves:[{fn:t=>-4*Math.cos(Math.sqrt(9.81/.11)*t),label:'s(t) = −4 cm cos(ωt)'}]});
files['schwingungen.html'].answers.schw_zeiger_rechnen+=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 320" role="img" aria-label="Zeigeraddition: 2 cm waagrecht, 5 cm unter 60 Grad, Summe 6,245 cm unter 43,9 Grad"><g fill="none" stroke-width="3"><path d="M70 255 L150 255" stroke="#1565c0"/><path d="M150 255 L250 82" stroke="#c0264d"/><path d="M70 255 L250 82" stroke="#15803d"/></g><g font-family="Arial,sans-serif" font-size="16" fill="#172033"><text x="80" y="278">2 cm</text><text x="195" y="195">5 cm, 60°</text><text x="75" y="125">6,245 cm, 43,9°</text></g></svg>`;
