files['wellen-book-Interferenz2.html'].extras[3][1][2]+=graph({title:'Idealisierte Trefferverteilungen',xMax:10,yMax:2,xLabel:'Schirmposition (relative Einheiten)',yLabel:'relative Häufigkeit',curves:[{fn:x=>Math.exp(-(((x-5)/2)**2)),label:'klassisch: glatte Summe'},{fn:x=>Math.exp(-(((x-5)/2)**2))*(1+Math.cos(2*Math.PI*(x-5))),label:'kohärent: Interferenz'}]});
files['wellen-book-Interferenz.html'].extras[5][0][2]+=scheme('Schirmgeometrie',['S₁, S₂: Abstand d','M → Schirm: e','E: seitlich a']);
files['Akustik-Versuche.html'].extras[3].push(['ak-material-skizzen','Lösungsskizzen: Schallerzeugung',scheme('Luftballon',['Ballonluft','Gummilippen ↔','Luft: Schall'])+scheme('Strohhalm',['Atemluft','Halmspitzen ↔','Luftsäule'])+scheme('Metallstreifen',['Tisch: fest','freies Ende ↑↓','Luft: Schall'])+scheme('Instrument-Frosch',['Stab an Rillen','Holz schwingt','Hohlraumluft'])+scheme('Kehlkopf',['Atemluft','Stimmlippen ↔','Luft: Stimme'])]);
files['Akustik-Versuche.html'].extras[4].push(['ak-stimmgabel-skizzen','Lösungsskizzen: Stimmgabel',scheme('Stimmgabel',['Zinken ↔','Stiel','Knopf am Körper'])+scheme('Wasserglas',['Zinkenspitzen ↔','Wasser','Spritzer/Wellen'])+graph({title:'Rußspur bei gleicher Ziehgeschwindigkeit',xMax:3,yMax:1,xLabel:'Ziehweg (relative Einheiten)',yLabel:'Auslenkung',curves:[{fn:x=>Math.exp(-.3*x)*Math.sin(6*Math.PI*x),label:'kräftiger Anschlag'},{fn:x=>.4*Math.exp(-.3*x)*Math.sin(6*Math.PI*x),label:'schwacher Anschlag'}]})]);
files['Akustik-Versuche.html'].extras[5].push(['ak-uebertragung-skizzen','Lösungsskizzen: Übertragungswege',scheme('Glockenläuten',['Löffel ↔','Schnur','Finger/Kopf','Innenohr'])+scheme('Flüssigkeiten',['Wecker/Glas','Wasser','Wannenwand','Ohr'])+scheme('Schnurtelefon',['Becherboden ↔','gespannte Schnur','Boden/Luft','Ohr'])+scheme('Kerzenflimmern',['Folie ↔','Luft in Röhre','Druckstoß','Flamme'])]);
